<?php
declare(strict_types=1);
require_once __DIR__.'/lab-results.php';
$reference=trim((string)($_GET['ref']??''));
$s=$pdo->prepare('SELECT l.*,p.PatientName,p.PatientPhone,v.VisitReference,d.DoctorName,d.UserID AS DoctorUserID FROM laboratory l JOIN patients p ON p.PatientID=l.PatientID LEFT JOIN visits v ON v.VisitID=l.VisitID LEFT JOIN doctors d ON d.DoctorID=l.DoctorID WHERE l.LaboratoryID=?');
$s->execute([$reference]);$order=$s->fetch();
if(!$order){http_response_code(404);exit('Laboratory result not found.');}
if(!tdc_can('laboratory.view') && !tdc_is_root_superadmin() && (int)$order['DoctorUserID']!==(int)$_SESSION['user_id']) tdc_forbidden();
$results=tdc_lab_result_details($pdo,$reference);
if($order['WorkflowStatus']!=='Completed' || ($results && array_filter($results,static fn($r)=>!in_array($r['ResultStatus'],['Completed','Reviewed'],true)))) {
    http_response_code(409);
    $safeId=htmlspecialchars($reference,ENT_QUOTES,'UTF-8');
    exit('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Print unavailable</title><style>body{margin:0;background:#f4f6fb;font:16px Arial;color:#1f2d70;display:grid;place-items:center;min-height:100vh}.notice{background:#fff;border:1px solid #dfe5f2;border-radius:14px;padding:32px;max-width:520px;box-shadow:0 12px 30px #1d305e18;text-align:center}a{display:inline-block;margin-top:18px;background:#2e3192;color:#fff;padding:10px 16px;border-radius:8px;text-decoration:none}</style></head><body><main class="notice"><h2>Print unavailable</h2><p>Laboratory result '.$safeId.' must be completed before it can be printed.</p><a href="auth/pages/laboratory.php?workspace=1&amp;lab_tab=test-result-entry">Return to Laboratory</a></main></body></html>');
}
$legacy=[];
if(!$results){$s=$pdo->prepare('SELECT * FROM laborderitems WHERE LaboratoryID=? ORDER BY LabOrderItemID');$s->execute([$reference]);$legacy=$s->fetchAll();}
$header=$pdo->query('SELECT CompanyName,CompanyAddress,PhoneNumbers,CompanyLogo FROM prescriptionsheader LIMIT 1')->fetch()?:[];
$e=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Laboratory Result <?= $e($reference) ?></title>
<style>@page{size:A4;margin:15mm}*{box-sizing:border-box}body{font:12px Arial,sans-serif;color:#172033;margin:0;background:#f3f4f8}.letterhead{display:flex;align-items:center;gap:14px}.brand-mark{width:64px;height:64px;display:grid;place-items:center}.brand-mark img{max-width:64px;max-height:64px;object-fit:contain}.report-label{margin-left:auto;text-align:right;color:#657089;font-size:10px;letter-spacing:.12em}.report-label strong{color:#2e3192;font-size:12px}.lab-result-paper{max-width:210mm;margin:18px auto;background:white;padding:16mm}header{border-bottom:3px solid #2e3192;padding-bottom:12px}h1{font-size:22px;color:#2e3192;margin:0 0 5px}h2{font-size:17px}h3{font-size:14px;margin-top:22px}.meta{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:18px 0}table{width:100%;border-collapse:collapse;table-layout:fixed}th,td{border:1px solid #cfd4df;padding:8px;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#eef0f7}thead{display:table-header-group}tr{break-inside:avoid}.print-toolbar{max-width:210mm;margin:0 auto 12px;text-align:right}.print-toolbar button{background:#2e3192;color:#fff;border:0;border-radius:7px;padding:10px 18px;font-weight:700;cursor:pointer}.review{margin:8px 0;padding:8px;border-left:3px solid #cfd4df;white-space:pre-wrap}@media print{.print-toolbar{display:none}body{background:white}.lab-result-paper{max-width:none;margin:0;padding:0}h3{break-after:avoid}}</style><link rel="stylesheet" href="assets/print-theme.css"></head><body><div class="print-toolbar"><button type="button" onclick="window.print()">Print A4</button></div><main class="lab-result-paper">
<header class="letterhead"><div class="brand-mark"><?php if (!empty($header['CompanyLogo'])): ?><img src="<?= $e((string)$header['CompanyLogo']) ?>" alt="Clinic logo"><?php elseif (is_file(dirname(__DIR__).'/uploads/tareydermacliniclogo.png')): ?><img src="uploads/tareydermacliniclogo.png" alt="Clinic logo"><?php endif; ?></div><div><h1><?= $e($header['CompanyName']??'Tarey Derma Clinic') ?></h1><div><?= $e($header['CompanyAddress']??'') ?></div><div><?= $e($header['PhoneNumbers']??'') ?></div></div><div class="report-label">LABORATORY<br><strong>RESULT REPORT</strong></div></header>
<h2>Laboratory Result</h2><section class="meta"><div>Patient: <?= $e($order['PatientName']) ?></div><div>Patient ID: <?= (int)$order['PatientID'] ?></div><div>Visit Reference: <?= $e($order['VisitReference']??'—') ?></div><div>Laboratory ID: <?= $e($reference) ?></div><div>Doctor: <?= $e($order['DoctorName']??'—') ?></div><div>Requested tests: <?= $e($order['TestName']) ?></div></section>
<?php foreach($results as $result): ?><section><h3><?= $e($result['ModernTestNameSnapshot']) ?></h3><p>Result status: <?= $e($result['ResultStatus']) ?> · Completed: <?= $e($result['CompletedAt']) ?> · <?= $e($result['CompletedByName']??'') ?></p>
<table><thead><tr><th>Parameter</th><th>Result</th><th>Unit</th><th>Reference range</th><th>Flag</th><th>Remark</th></tr></thead><tbody><?php foreach($result['parameters'] as $p): ?><tr><td><?= $e($p['ParameterNameSnapshot']) ?></td><td><?= $e($p['DisplayResult']) ?></td><td><?= $e($p['UnitNameSnapshot']) ?></td><td><?= $e($p['ReferenceRangeSnapshot']) ?></td><td><?= $e($p['FlagNameSnapshot']?:$p['FlagCodeSnapshot']) ?></td><td><?= $e($p['Remark']) ?></td></tr><?php endforeach; ?></tbody></table>
<?php foreach($result['reviews'] as $review): ?><div class="review"><?= $e($review['Action']) ?> · <?= $e($review['ReviewerName']??'Former user') ?> · <?= $e($review['PerformedAt']) ?><br><?= $e($review['Notes']) ?></div><?php endforeach; ?></section><?php endforeach; ?>
<?php if(!$results): ?><h3>Legacy result</h3><p>Completed: <?= $e($order['ResultDate']) ?> · Reviewed: <?= $e($order['ReviewedAt']??'—') ?></p><table><thead><tr><th>Test</th><th>Result</th><th>Clinical result</th></tr></thead><tbody><?php if(!$legacy)$legacy=[['TestName'=>$order['TestName'],'Result'=>$order['Result'],'ClinicalResult'=>$order['ClinicalResult']]];foreach($legacy as $item): ?><tr><td><?= $e($item['TestName']) ?></td><td><?= $e($item['Result']) ?></td><td><?= $e($item['ClinicalResult']) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?>
</main></body></html>
